@@ -0,0 +1,74 @@
+import { useState, useEffect } from 'react';
+import { Atividade, Sala } from '../api/types';
+import { api } from '../api/client';
+
+export const DIAS_SEMANA = [
+  { data: '2026-10-19', label: '19/10/2026 (Seg)' },
+  { data: '2026-10-20', label: '20/10/2026 (Ter)' },
+  { data: '2026-10-21', label: '21/10/2026 (Qua)' },
+  { data: '2026-10-22', label: '22/10/2026 (Qui)' },
+  { data: '2026-10-23', label: '23/10/2026 (Sex)' },
+];
+
+export function useProgramacao(selectedUserId: string | null, apiClient = api) {
+  const [dia, setDia] = useState<string>('2026-10-19');
+  const [tipo, setTipo] = useState<string>('');
+  const [atividades, setAtividades] = useState<Atividade[]>([]);
+  const [salas, setSalas] = useState<Sala[]>([]);
+  const [loading, setLoading] = useState<boolean>(false);
+  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);
+
+  useEffect(() => {
+    if (!selectedUserId) {
+      setAtividades([]);
+      setSalas([]);
+      setLoading(false);
+      setError(null);
+      return;
+    }
+
+    let isMounted = true;
+    setLoading(true);
+    setError(null);
+
+    Promise.all([
+      apiClient.getSalas(),
+      apiClient.getAtividades({
+        dia,
+        tipo: tipo ? (tipo as 'palestra' | 'minicurso') : undefined,
+      }),
+    ])
+      .then(([salasRes, atividadesRes]) => {
+        if (isMounted) {
+          setSalas(salasRes);
+          setAtividades(atividadesRes);
+          setLoading(false);
+        }
+      })
+      .catch((err: any) => {
+        if (isMounted) {
+          setError({
+            erro: err.erro || 'ERRO_DESCONHECIDO',
+            mensagem: err.mensagem || err.message || 'Erro ao carregar programação',
+          });
+          setLoading(false);
+        }
+      });
+
+    return () => {
+      isMounted = false;
+    };
+  }, [selectedUserId, dia, tipo, apiClient]);
+
+  return {
+    dia,
+    setDia,
+    tipo,
+    setTipo,
+    atividades,
+    salas,
+    loading,
+    error,
+    DIAS_SEMANA,
+  };
+}

parts.text:
Continue na branch `feat/m1-interface`, após o commit da fundação da interface.

Implemente com TDD somente a tela de programação: listagem, navegação por dia, filtro por tipo e estados visuais. Preserve os 14 testes atuais.

Leia R17–R20, R36, R37 e R40 de `specs/M1-grade.md`. Não altere a API.

Com um usuário selecionado, a interface deve:

- carregar atividades pelo cliente centralizado;
- exibir o título “Programação”;
- permitir navegar pelos dias 19 a 23 de outubro de 2026;
- iniciar no dia 19/10/2026;
- filtrar por `palestra`, `minicurso` ou todos os tipos;
- combinar `dia` e `tipo` nas chamadas ao cliente;
- apresentar as atividades na ordem recebida da API;
- exibir título, tipo, sala, primeiro horário, vagas e situação;
- destacar visualmente atividades canceladas;
- não duplicar regras de negócio da API.

Implemente os estados:

- indicador “Carregando programação...” enquanto a promessa estiver pendente;
- mensagem explícita quando a lista estiver vazia;
- erro contendo o código e a mensagem recebidos da API;
- programação visível após sucesso;
- nova consulta quando dia ou tipo mudar.

Use um cliente falso injetável nos testes. Nenhum teste pode iniciar a API ou realizar rede real.

Adicione testes para:

1. carregamento pendente;
2. listagem com sucesso;
3. lista vazia;
4. erro exibindo código e mensagem;
5. troca do dia enviado ao cliente;
6. filtro por tipo enviado ao cliente;
7. combinação de dia e tipo;
8. indicação visual de atividade cancelada.

Use HTML semântico, botões acessíveis para os dias, rótulo para o filtro e layout responsivo. Crie ou ajuste CSS sem adicionar bibliotecas.

Não implemente ainda:

- página de detalhes;
- formulário de criação;
- edição;
- cancelamento;
- controles administrativos.

Arquivos esperados:

- `app/src/App.tsx`;
- `app/src/App.test.tsx`;
- componentes e hooks próprios da programação;
- `app/src/styles.css`;
- ajustes mínimos em tipos ou cliente, se necessários.

Ao terminar, execute testes, typecheck, build, `git diff --check`, `git status --short` e `git diff --stat`.

Resultado esperado: 22 testes aprovados na interface, contando os 14 atuais. Não faça commit nem push. Relate os ciclos TDD, os filtros enviados ao cliente, os estados visuais e os arquivos alterados.

