import { useState, useEffect } from 'react';
import { Atividade, Sala } from '../api/types';
import { api } from '../api/client';

export function useAtividadeDetalhe(id: string | undefined, selectedUserId: string | null, apiClient = api) {
  const [atividade, setAtividade] = useState<Atividade | null>(null);
  const [salas, setSalas] = useState<Sala[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);

  useEffect(() => {
    if (!id || !selectedUserId) {
      setAtividade(null);
      setSalas([]);
      setLoading(false);
      setError(null);
      return;
    }

    let isMounted = true;
    setLoading(true);
    setError(null);

    Promise.all([
      apiClient.getSalas(),
      apiClient.getAtividade(id),
    ])
      .then(([salasRes, atvRes]) => {
        if (isMounted) {
          setSalas(salasRes);
          setAtividade(atvRes);
          setLoading(false);
        }
      })
      .catch((err: any) => {
        if (isMounted) {
          setError({
            erro: err.erro || 'ERRO_DESCONHECIDO',
            mensagem: err.mensagem || err.message || 'Erro ao carregar detalhes da atividade',
          });
          setLoading(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, [id, selectedUserId, apiClient]);

  return {
    atividade,
    salas,
    loading,
    error,
  };
}

import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { useAtividadeDetalhe } from '../hooks/useAtividadeDetalhe';
import { M2ExtensionPoint } from './M2ExtensionPoint';
import { api } from '../api/client';

interface AtividadeDetalheProps {
  selectedUserId: string | null;
  apiClient?: typeof api;
}

export function AtividadeDetalhe({ selectedUserId, apiClient = api }: AtividadeDetalheProps) {
  const { id } = useParams<{ id: string }>();
  const { atividade, salas, loading, error } = useAtividadeDetalhe(id, selectedUserId, apiClient);

  const getSalaNome = (salaId: string) => {
    const sala = salas.find((s) => s.id === salaId);
    return sala ? sala.nome : salaId;
  };

  const formatarDataHora = (isoString?: string) => {
    if (!isoString) return '';
    try {
      const date = new Date(isoString);
      return date.toLocaleString();
    } catch {
      return isoString;
    }
  };

  if (!selectedUserId) {
    return (
      <div>
        <p>Nenhum usuário selecionado. Por favor, selecione um usuário de demonstração para acessar o sistema.</p>
        <p>
          <Link to="/">Voltar para a programação</Link>
        </p>
      </div>
    );
  }

  return (
    <div className="atividade-detalhe-container" style={{ padding: '1rem 0' }}>
      <p>
        <Link to="/" className="voltar-link">Voltar para a programação</Link>
      </p>

      {loading && <p>Carregando atividade...</p>}

      {error && (
        <div className="error-message" style={{ color: 'red', margin: '1rem 0' }}>
          Erro ({error.erro}): {error.mensagem}
        </div>
      )}

      {!loading && !error && atividade && (
        <div>
          {atividade.situacao === 'cancelada' && (
            <div style={{ color: 'red', fontWeight: 'bold', marginBottom: '1rem' }}>
              Atividade Cancelada
            </div>
          )}

          <h2>{atividade.titulo}</h2>
          <p><strong>Tipo:</strong> {atividade.tipo}</p>
          <p><strong>Sala:</strong> {getSalaNome(atividade.salaId)}</p>
          <p><strong>Vagas:</strong> {atividade.vagas}</p>
          <p><strong>Carga Horária:</strong> {atividade.cargaHorariaMinutos} minutos</p>
          <p><strong>Situação:</strong> {atividade.situacao}</p>
          <p><strong>Ocupadas:</strong> {atividade.ocupadas}</p>
          <p><strong>Vagas Restantes:</strong> {atividade.vagasRestantes}</p>
          <p><strong>Pessoas em Espera:</strong> {atividade.emEspera}</p>

          <h3>Encontros</h3>
          {atividade.encontros && atividade.encontros.length > 0 ? (
            <ul>
              {atividade.encontros.map((enc) => (
                <li key={enc.id}>
                  Início: {formatarDataHora(enc.inicio)} | Fim: {formatarDataHora(enc.fim)}
                </li>
              ))}
            </ul>
          ) : (
            <p>Nenhum encontro cadastrado.</p>
          )}

          <M2ExtensionPoint />
        </div>
      )}
    </div>
  );
}

