+  const [successMessage, setSuccessMessage] = useState<string | null>(null);
+
+  useEffect(() => {
+    if (!selectedUserId) return;
+    apiClient.getSalas()
+      .then((res) => {
+        setSalas(res);
+        if (res.length > 0 && !salaId) {
+          setSalaId(res[0].id);
+        }
+      })
+      .catch(() => {});
+  }, [selectedUserId, apiClient]);
+
+  if (!selectedUserId || userPapel !== 'organizacao') {
