import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { Atividade, Sala } from '../api/types';
import { api } from '../api/client';

interface EditarAtividadeProps {
  selectedUserId: string | null;
  userPapel?: string;
  apiClient?: typeof api;
}

export function EditarAtividade({ selectedUserId, userPapel, apiClient = api }: EditarAtividadeProps) {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [atividade, setAtividade] = useState<Atividade | null>(null);
  const [salas, setSalas] = useState<Sala[]>([]);
  const [titulo, setTitulo] = useState('');
  const [vagas, setVagas] = useState(1);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  useEffect(() => {
    if (!id || !selectedUserId || userPapel !== 'organizacao') return;
    setLoading(true);
    Promise.all([
      apiClient.getSalas(),
      apiClient.getAtividade(id),
    ])
      .then(([salasRes, atvRes]) => {
        setSalas(salasRes);
        setAtividade(atvRes);
        setTitulo(atvRes.titulo);
        setVagas(atvRes.vagas);
        setLoading(false);
      })
      .catch((err: any) => {
        setError({
          erro: err.erro || 'ERRO_DESCONHECIDO',
          mensagem: err.mensagem || err.message || 'Erro ao carregar atividade',
        });
        setLoading(false);
      });
  }, [id, selectedUserId, userPapel, apiClient]);

  if (!selectedUserId || userPapel !== 'organizacao') {
    return (
      <div>
        <p>Acesso negado ou usuário não autorizado.</p>
        <Link to="/">Voltar para a programação</Link>
      </div>
    );
  }

  const getSalaNome = (salaId: string) => {
    const sala = salas.find((s) => s.id === salaId);
    return sala ? sala.nome : salaId;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting || !id) return;

    setSubmitting(true);
    setError(null);
    setSuccessMessage(null);

    try {
      await apiClient.updateAtividade(id, {
        titulo,
        vagas: Number(vagas),
      });

      setSuccessMessage('Atividade alterada com sucesso!');
      setTimeout(() => {
        navigate(`/atividades/${id}`);
      }, 100);
    } catch (err: any) {
      setError({
        erro: err.erro || 'ERRO_DESCONHECIDO',
        mensagem: err.mensagem || err.message || 'Erro ao editar atividade',
      });
      setSubmitting(false);
    }
  };

  if (loading) {
    return <p>Carregando atividade...</p>;
  }

  return (
    <div className="editar-atividade-container" style={{ padding: '1rem 0' }}>
      <p>
        <Link to={`/atividades/${id}`} className="voltar-detalhe-link">Voltar ao detalhe</Link>
      </p>

      <h2>Editar Atividade</h2>

      {successMessage && <div className="success-message" style={{ color: 'green' }}>{successMessage}</div>}

      {error && (
        <div className="error-message" style={{ color: 'red', margin: '1rem 0' }}>
          Erro ({error.erro}): {error.mensagem}
        </div>
      )}

      {atividade && (
        <form onSubmit={handleSubmit} style={{ display: 'grid', gap: '1rem', maxWidth: '600px' }}>
          <div>
            <label htmlFor="edit-titulo-input">Título:</label>
            <input
              id="edit-titulo-input"
              type="text"
              value={titulo}
              onChange={(e) => setTitulo(e.target.value)}
              required
              style={{ display: 'block', width: '100%', padding: '0.5rem' }}
            />
          </div>

          <div>
            <label htmlFor="edit-vagas-input">Vagas:</label>
            <input
              id="edit-vagas-input"
              type="number"
              value={vagas}
              onChange={(e) => setVagas(Number(e.target.value))}
              min={1}
              required
              style={{ display: 'block', width: '100%', padding: '0.5rem' }}
            />
          </div>

          <div style={{ background: '#f8f9fa', padding: '1rem', borderRadius: '4px' }}>
            <p><strong>Tipo (Não editável):</strong> <span>{atividade.tipo}</span></p>
            <p><strong>Sala (Não editável):</strong> <span>{getSalaNome(atividade.salaId)}</span></p>
            <p><strong>Carga Horária (Não editável):</strong> <span>{atividade.cargaHorariaMinutos} minutos</span></p>
          </div>

          <div style={{ display: 'flex', gap: '1rem' }}>
            <button
              type="submit"
              disabled={submitting}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: submitting ? '#cccccc' : '#007bff',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: submitting ? 'not-allowed' : 'pointer',
              }}
            >
              {submitting ? 'Salvando...' : 'Salvar Alterações'}
            </button>
            <Link
              to={`/atividades/${id}`}
              className="voltar-sem-salvar"
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: '#6c757d',
                color: '#fff',
                borderRadius: '4px',
                textDecoration: 'none',
                display: 'inline-block',
              }}
            >
              Voltar sem salvar
            </Link>
          </div>
        </form>
      )}
    </div>
  );
}

import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { useAtividadeDetalhe } from '../hooks/useAtividadeDetalhe';
import { M2ExtensionPoint } from './M2ExtensionPoint';
import { api } from '../api/client';

interface AtividadeDetalheProps {
  selectedUserId: string | null;
  userPapel?: string;
  apiClient?: typeof api;
}

export function AtividadeDetalhe({ selectedUserId, userPapel, apiClient = api }: AtividadeDetalheProps) {
  const { id } = useParams<{ id: string }>();
  const { atividade, salas, loading, error } = useAtividadeDetalhe(id, selectedUserId, apiClient);

  const getSalaNome = (salaId: string) => {
    const sala = salas.find((s) => s.id === salaId);
    return sala ? sala.nome : salaId;
  };

  const formatarDataHora = (isoString?: string) => {
    if (!isoString) return '';
    try {
      const date = new Date(isoString);
      return date.toLocaleString();
    } catch {
      return isoString;
    }
  };

  if (!selectedUserId) {
    return (
      <div>
        <p>Nenhum usuário selecionado. Por favor, selecione um usuário de demonstração para acessar o sistema.</p>
        <p>
          <Link to="/">Voltar para a programação</Link>
        </p>
      </div>
    );
  }

  return (
    <div className="atividade-detalhe-container" style={{ padding: '1rem 0' }}>
      <p>
        <Link to="/" className="voltar-link">Voltar para a programação</Link>
      </p>

      {userPapel === 'organizacao' && atividade && (
        <p style={{ margin: '1rem 0' }}>
          <Link
            to={`/atividades/${atividade.id}/editar`}
            className="editar-atividade-link"
            style={{
              padding: '0.4rem 0.8rem',
              backgroundColor: '#ffc107',
              color: '#000',
              borderRadius: '4px',
              textDecoration: 'none',
              display: 'inline-block',
            }}
          >
            Editar atividade
          </Link>
        </p>
      )}

      {loading && <p>Carregando atividade...</p>}

      {error && (
        <div className="error-message" style={{ color: 'red', margin: '1rem 0' }}>
          Erro ({error.erro}): {error.mensagem}
        </div>
      )}

      {!loading && !error && atividade && (
        <div>
          {atividade.situacao === 'cancelada' && (
            <div style={{ color: 'red', fontWeight: 'bold', marginBottom: '1rem' }}>
              Atividade Cancelada
            </div>
          )}

          <h2 data-testid="detalhe-titulo">{atividade.titulo}</h2>
          <p><strong>Tipo:</strong> <span data-testid="detalhe-tipo">{atividade.tipo}</span></p>
          <p><strong>Sala:</strong> <span data-testid="detalhe-sala">{getSalaNome(atividade.salaId)}</span></p>
          <p><strong>Vagas:</strong> <span data-testid="detalhe-vagas">{atividade.vagas}</span></p>
          <p><strong>Carga Horária:</strong> <span data-testid="detalhe-carga">{atividade.cargaHorariaMinutos}</span> minutos</p>
          <p><strong>Situação:</strong> <span data-testid="detalhe-situacao">{atividade.situacao}</span></p>
          <p><strong>Ocupadas:</strong> <span data-testid="detalhe-ocupadas">{atividade.ocupadas}</span></p>
          <p><strong>Vagas Restantes:</strong> <span data-testid="detalhe-vagas-restantes">{atividade.vagasRestantes}</span></p>
          <p><strong>Pessoas em Espera:</strong> <span data-testid="detalhe-em-espera">{atividade.emEspera}</span></p>

          <h3>Encontros</h3>
          {atividade.encontros && atividade.encontros.length > 0 ? (
            <ul>
              {atividade.encontros.map((enc) => (
                <li key={enc.id}>
                  Início: {formatarDataHora(enc.inicio)} | Fim: {formatarDataHora(enc.fim)}
                </li>
              ))}
            </ul>
          ) : (
            <p>Nenhum encontro cadastrado.</p>
          )}

          <M2ExtensionPoint />
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { BrowserRouter, MemoryRouter, Routes, Route } from 'react-router-dom';
import { useSelectedUser } from './hooks/useSelectedUser';
import { UserSelector } from './components/UserSelector';
import { useProgramacao, DIAS_SEMANA } from './hooks/useProgramacao';
import { Programacao } from './components/Programacao';
import { AtividadeDetalhe } from './components/AtividadeDetalhe';
import { CriarAtividade } from './components/CriarAtividade';
import { EditarAtividade } from './components/EditarAtividade';
import { api } from './api/client';

interface AppProps {
  apiClient?: typeof api;
  initialEntries?: string[];
}

export function App({ apiClient = api, initialEntries }: AppProps) {
  const { selectedUser, selectUser, users } = useSelectedUser();
  const {
    dia,
    setDia,
    tipo,
    setTipo,
    atividades,
    salas,
    loading,
    error,
  } = useProgramacao(selectedUser?.id || null, apiClient);

  const RouterComponent = initialEntries ? MemoryRouter : BrowserRouter;
  const routerProps = initialEntries ? { initialEntries } : {};

  return (
    <RouterComponent {...routerProps}>
      <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
        <h1>Semana Acadêmica</h1>

        <UserSelector
          selectedUser={selectedUser}
          onSelectUser={selectUser}
          users={users}
        />

        <div style={{ marginTop: '2rem' }} data-testid="active-user-info">
          {selectedUser ? (
            <div>
              <p>Usuário ativo: <strong>{selectedUser.nome}</strong> ({selectedUser.papel})</p>
              <Routes>
                <Route
                  path="/"
                  element={
                    <Programacao
                      dia={dia}
                      setDia={setDia}
                      tipo={tipo}
                      setTipo={setTipo}
                      atividades={atividades}
                      salas={salas}
                      loading={loading}
                      error={error}
                      dias={DIAS_SEMANA}
                      userPapel={selectedUser.papel}
                    />
                  }
                />
                <Route
                  path="/atividades/nova"
                  element={<CriarAtividade selectedUserId={selectedUser.id} userPapel={selectedUser.papel} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id/editar"
                  element={<EditarAtividade selectedUserId={selectedUser.id} userPapel={selectedUser.papel} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id"
                  element={<AtividadeDetalhe selectedUserId={selectedUser.id} userPapel={selectedUser.papel} apiClient={apiClient} />}
                />
              </Routes>
            </div>
          ) : (
            <div>
              <p>Nenhum usuário selecionado. Por favor, selecione um usuário de demonstração para acessar o sistema.</p>
              <Routes>
                <Route
                  path="/atividades/nova"
                  element={<CriarAtividade selectedUserId={null} userPapel={undefined} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id/editar"
                  element={<EditarAtividade selectedUserId={null} userPapel={undefined} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id"
                  element={<AtividadeDetalhe selectedUserId={null} apiClient={apiClient} />}
                />
                <Route path="*" element={null} />
              </Routes>
            </div>
          )}
        </div>
      </div>
    </RouterComponent>
  );
}

export default App;

