export function formatarHoraBrasilia(isoString?: string): string {
  if (!isoString) return '';
  try {
    const date = new Date(isoString);
    return new Intl.DateTimeFormat('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      hour: '2-digit',
      minute: '2-digit',
    }).format(date);
  } catch {
    return isoString;
  }
}

export function formatarDataHoraBrasilia(isoString?: string): string {
  if (!isoString) return '';
  try {
    const date = new Date(isoString);
    return new Intl.DateTimeFormat('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      dateStyle: 'short',
      timeStyle: 'medium',
    }).format(date);
  } catch {
    return isoString;
  }
}

export interface Sala {
  id: string;
  nome: string;
  capacidade: number;
}

export interface EncontroInput {
  inicio: string;
  fim: string;
}

export interface Encontro extends EncontroInput {
  id: string;
}

export interface AtividadeInput {
  titulo?: string;
  tipo?: "palestra" | "minicurso";
  salaId?: string;
  vagas?: number;
  encontros?: EncontroInput[];
}

export interface CreateAtividadeDTO {
  titulo: string;
  tipo: "palestra" | "minicurso";
  salaId: string;
  vagas: number;
  encontros: EncontroInput[];
}

export interface UpdateAtividadeDTO {
  titulo?: string;
  vagas?: number;
}

export interface Atividade {
  id: string;
  titulo: string;
  tipo: "palestra" | "minicurso";
  salaId: string;
  vagas: number;
  encontros: Encontro[];
  cargaHorariaMinutos: number;
  situacao: "prevista" | "em_andamento" | "encerrada" | "cancelada";
  ocupadas: number;
  vagasRestantes: number;
  emEspera: number;
}

export interface ApiErrorResponse {
  erro: string;
  mensagem: string;
}

export class ApiError extends Error {
  erro: string;
  mensagem: string;
  status: number;

  constructor(status: number, erro: string, mensagem: string) {
    super(mensagem);
    this.name = 'ApiError';
    this.status = status;
    this.erro = erro;
    this.mensagem = mensagem;
  }
}

import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Sala } from '../api/types';
import { api } from '../api/client';

interface CriarAtividadeProps {
  selectedUserId: string | null;
  userPapel?: string;
  apiClient?: typeof api;
}

export function CriarAtividade({ selectedUserId, userPapel, apiClient = api }: CriarAtividadeProps) {
  const navigate = useNavigate();
  const [salas, setSalas] = useState<Sala[]>([]);
  const [loadingSalas, setLoadingSalas] = useState(true);
  const [salasError, setSalasError] = useState<{ erro: string; mensagem: string } | null>(null);
  const [titulo, setTitulo] = useState('');
  const [tipo, setTipo] = useState<'palestra' | 'minicurso'>('palestra');
  const [salaId, setSalaId] = useState('');
  const [vagas, setVagas] = useState(10);
  const [encontros, setEncontros] = useState<Array<{ inicio: string; fim: string }>>([
    { inicio: '', fim: '' },
  ]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  useEffect(() => {
    if (!selectedUserId) {
      setLoadingSalas(false);
      return;
    }
    setLoadingSalas(true);
    setSalasError(null);
    apiClient.getSalas()
      .then((res) => {
        setSalas(res);
        if (res.length > 0 && !salaId) {
          setSalaId(res[0].id);
        }
        setLoadingSalas(false);
      })
      .catch((err: any) => {
        setSalasError({
          erro: err.erro || 'ERRO_DESCONHECIDO',
          mensagem: err.mensagem || err.message || 'Erro ao carregar salas',
        });
        setLoadingSalas(false);
      });
  }, [selectedUserId, apiClient]);

  if (!selectedUserId || userPapel !== 'organizacao') {
    return (
      <div>
        <p>Acesso negado ou usuário não autorizado.</p>
        <Link to="/">Voltar para a programação</Link>
      </div>
    );
  }

  const handleAddEncontro = () => {
    setEncontros([...encontros, { inicio: '', fim: '' }]);
  };

  const handleRemoveEncontro = (index: number) => {
    if (encontros.length > 1) {
      setEncontros(encontros.filter((_, i) => i !== index));
    }
  };

  const handleEncontroChange = (index: number, field: 'inicio' | 'fim', value: string) => {
    const updated = [...encontros];
    updated[index][field] = value;
    setEncontros(updated);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting || loadingSalas || salasError) return;

    setSubmitting(true);
    setError(null);
    setSuccessMessage(null);

    const formattedEncontros = encontros.map((enc) => ({
      inicio: enc.inicio ? `${enc.inicio}:00-03:00` : '',
      fim: enc.fim ? `${enc.fim}:00-03:00` : '',
    }));

    try {
      const novaAtividade = await apiClient.createAtividade({
        titulo,
        tipo,
        salaId: salaId || (salas[0]?.id ?? ''),
        vagas: Number(vagas),
        encontros: formattedEncontros,
      });

      setSuccessMessage('Atividade criada com sucesso!');
      setTimeout(() => {
        navigate(`/atividades/${novaAtividade.id}`);
      }, 100);
    } catch (err: any) {
      setError({
        erro: err.erro || 'ERRO_DESCONHECIDO',
        mensagem: err.mensagem || err.message || 'Erro ao criar atividade',
      });
      setSubmitting(false);
    }
  };

  return (
    <div className="criar-atividade-container" style={{ padding: '1rem 0' }}>
      <p>
        <Link to="/">Voltar para a programação</Link>
      </p>

      <h2>Criar Atividade</h2>

      {loadingSalas && <p role="status" aria-live="polite">Carregando salas...</p>}

      {salasError && (
        <div className="error-message" role="alert">
          Erro ({salasError.erro}): {salasError.mensagem}
        </div>
      )}

      {successMessage && <div className="success-message" role="status" aria-live="polite">{successMessage}</div>}

      {error && (
        <div className="error-message" role="alert">
          Erro ({error.erro}): {error.mensagem}
        </div>
      )}

      {!loadingSalas && !salasError && (
        <form onSubmit={handleSubmit} style={{ display: 'grid', gap: '1rem', maxWidth: '600px' }}>
          <div>
            <label htmlFor="titulo-input">Título:</label>
            <input
              id="titulo-input"
              type="text"
              value={titulo}
              onChange={(e) => setTitulo(e.target.value)}
              required
              style={{ display: 'block', width: '100%', padding: '0.5rem' }}
            />
          </div>

          <div>
            <label htmlFor="tipo-select">Tipo:</label>
            <select
              id="tipo-select"
              value={tipo}
              onChange={(e) => setTipo(e.target.value as 'palestra' | 'minicurso')}
              style={{ display: 'block', width: '100%', padding: '0.5rem' }}
            >
              <option value="palestra">Palestra</option>
              <option value="minicurso">Minicurso</option>
            </select>
          </div>

          <div>
            <label htmlFor="sala-select">Sala:</label>
            <select
              id="sala-select"
              value={salaId}
              onChange={(e) => setSalaId(e.target.value)}
              style={{ display: 'block', width: '100%', padding: '0.5rem' }}
            >
              {salas.map((sala) => (
                <option key={sala.id} value={sala.id}>
                  {sala.nome} (Capacidade: {sala.capacidade})
                </option>
              ))}
            </select>
          </div>

          <div>
            <label htmlFor="vagas-input">Vagas:</label>
            <input
              id="vagas-input"
              type="number"
              value={vagas}
              onChange={(e) => setVagas(Number(e.target.value))}
              min={1}
              required
              style={{ display: 'block', width: '100%', padding: '0.5rem' }}
            />
          </div>

          <fieldset style={{ border: '1px solid #ccc', padding: '1rem', borderRadius: '4px' }}>
            <legend>Encontros</legend>
            {encontros.map((enc, index) => (
              <div key={index} style={{ display: 'flex', gap: '1rem', marginBottom: '0.5rem', alignItems: 'center' }}>
                <div>
                  <label htmlFor={`encontro-inicio-${index}`}>Início:</label>
                  <input
                    id={`encontro-inicio-${index}`}
                    type="datetime-local"
                    value={enc.inicio}
                    onChange={(e) => handleEncontroChange(index, 'inicio', e.target.value)}
                    required
                  />
                </div>
                <div>
                  <label htmlFor={`encontro-fim-${index}`}>Fim:</label>
                  <input
                    id={`encontro-fim-${index}`}
                    type="datetime-local"
                    value={enc.fim}
                    onChange={(e) => handleEncontroChange(index, 'fim', e.target.value)}
                    required
                  />
                </div>
                {encontros.length > 1 && (
                  <button
                    type="button"
                    onClick={() => handleRemoveEncontro(index)}
                    style={{ alignSelf: 'flex-end', padding: '0.4rem' }}
                  >
                    Remover
                  </button>
                )}
              </div>
            ))}
            <button type="button" onClick={handleAddEncontro} style={{ marginTop: '0.5rem', padding: '0.4rem 0.8rem' }}>
              Adicionar Encontro
            </button>
          </fieldset>

          <button
            type="submit"
            disabled={submitting || loadingSalas || !!salasError}
            style={{
              padding: '0.75rem',
              backgroundColor: submitting || loadingSalas || !!salasError ? '#cccccc' : '#28a745',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: submitting || loadingSalas || !!salasError ? 'not-allowed' : 'pointer',
            }}
          >
            {submitting ? 'Criando atividade...' : 'Salvar Atividade'}
          </button>
        </form>
      )}
    </div>
  );
}

import React from 'react';
import { Link } from 'react-router-dom';
import { Atividade, Sala } from '../api/types';
import { formatarHoraBrasilia } from '../utils/date';

interface ProgramacaoProps {
  dia: string;
  setDia: (dia: string) => void;
  tipo: string;
  setTipo: (tipo: string) => void;
  atividades: Atividade[];
  salas: Sala[];
  loading: boolean;
  error: { erro: string; mensagem: string } | null;
  dias: Array<{ data: string; label: string }>;
  userPapel?: string;
}

export function Programacao({
  dia,
  setDia,
  tipo,
  setTipo,
  atividades,
  salas,
  loading,
  error,
  dias,
  userPapel,
}: ProgramacaoProps) {
  const getSalaNome = (salaId: string) => {
    const sala = salas.find((s) => s.id === salaId);
    return sala ? sala.nome : salaId;
  };

  return (
    <div className="programacao-container" style={{ marginTop: '2rem' }}>
      <h2>Programação</h2>

      {userPapel === 'organizacao' && (
        <div style={{ margin: '1rem 0' }}>
          <Link
            to="/atividades/nova"
            className="criar-atividade-link"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#28a745',
              color: '#fff',
              borderRadius: '4px',
              textDecoration: 'none',
              display: 'inline-block',
            }}
          >
            Criar atividade
          </Link>
        </div>
      )}

      <div className="filtros-container" style={{ margin: '1rem 0', display: 'flex', gap: '1rem', flexWrap: 'wrap', alignItems: 'center' }}>
        <div className="dias-navegacao" style={{ display: 'flex', gap: '0.5rem' }}>
          {dias.map((d) => (
            <button
              key={d.data}
              type="button"
              onClick={() => setDia(d.data)}
              className={dia === d.data ? 'active-day' : ''}
              style={{
                padding: '0.5rem 1rem',
                backgroundColor: dia === d.data ? '#007bff' : '#f8f9fa',
                color: dia === d.data ? '#fff' : '#333',
                border: '1px solid #ccc',
                borderRadius: '4px',
                cursor: 'pointer',
              }}
            >
              {d.label}
            </button>
          ))}
        </div>

        <div className="tipo-filtro" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <label htmlFor="tipo-select">Filtrar por tipo:</label>
          <select
            id="tipo-select"
            value={tipo}
            onChange={(e) => setTipo(e.target.value)}
            style={{ padding: '0.4rem', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="">Todos os tipos</option>
            <option value="palestra">Palestra</option>
            <option value="minicurso">Minicurso</option>
          </select>
        </div>
      </div>

      {loading && <p role="status" aria-live="polite">Carregando programação...</p>}

      {error && (
        <div className="error-message" role="alert">
          Erro ({error.erro}): {error.mensagem}
        </div>
      )}

      {!loading && !error && atividades.length === 0 && (
        <p className="empty-message" role="status" aria-live="polite">Nenhuma atividade encontrada para os filtros selecionados.</p>
      )}

      {!loading && !error && atividades.length > 0 && (
        <ul className="atividades-list" style={{ listStyle: 'none', padding: 0, display: 'grid', gap: '1rem' }}>
          {atividades.map((atv) => {
            const isCancelada = atv.situacao === 'cancelada';
            const primeiroEncontro = atv.encontros?.[0];
            return (
              <li
                key={atv.id}
                className={`atividade-item ${isCancelada ? 'atividade-cancelada' : ''}`}
                style={{
                  padding: '1rem',
                  border: '1px solid #ddd',
                  borderRadius: '6px',
                  backgroundColor: isCancelada ? '#fff5f5' : '#fff',
                  opacity: isCancelada ? 0.8 : 1,
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div>
                    <h3 style={{ margin: '0 0 0.5rem 0', textDecoration: isCancelada ? 'line-through' : 'none' }}>
                      {atv.titulo} {isCancelada && <span style={{ color: 'red', fontSize: '0.8rem', textDecoration: 'none' }}>(Cancelada)</span>}
                    </h3>
                    <p style={{ margin: '0.2rem 0' }}>
                      <strong>Tipo:</strong> {atv.tipo}
                    </p>
                    <p style={{ margin: '0.2rem 0' }}>
                      <strong>Sala:</strong> {getSalaNome(atv.salaId)}
                    </p>
                    {primeiroEncontro && (
                      <p style={{ margin: '0.2rem 0' }}>
                        <strong>Início:</strong> {formatarHoraBrasilia(primeiroEncontro.inicio)}
                      </p>
                    )}
                    <p style={{ margin: '0.2rem 0' }}>
                      <strong>Vagas:</strong> {atv.vagas} (Restantes: {atv.vagasRestantes})
                    </p>
                    <p style={{ margin: '0.2rem 0' }}>
                      <strong>Situação:</strong> {atv.situacao}
                    </p>
                    <p style={{ marginTop: '0.5rem' }}>
                      <Link to={`/atividades/${atv.id}`} className="ver-detalhes-link">
                        Ver detalhes
                      </Link>
                    </p>
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useAtividadeDetalhe } from '../hooks/useAtividadeDetalhe';
import { M2ExtensionPoint } from './M2ExtensionPoint';
import { api } from '../api/client';
import { formatarDataHoraBrasilia } from '../utils/date';

interface AtividadeDetalheProps {
  selectedUserId: string | null;
  userPapel?: string;
  apiClient?: typeof api;
}

export function AtividadeDetalhe({ selectedUserId, userPapel, apiClient = api }: AtividadeDetalheProps) {
  const { id } = useParams<{ id: string }>();
  const { atividade, salas, loading, error, reload } = useAtividadeDetalhe(id, selectedUserId, apiClient);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [cancelError, setCancelError] = useState<{ erro: string; mensagem: string } | null>(null);
  const [cancelSuccessMessage, setCancelSuccessMessage] = useState<string | null>(null);

  const isCancelada = atividade?.situacao === 'cancelada';

  const getSalaNome = (salaId: string) => {
    const sala = salas.find((s) => s.id === salaId);
    return sala ? sala.nome : salaId;
  };

  const handleConfirmCancel = async () => {
    if (cancelling || !atividade) return;
    setCancelling(true);
    setCancelError(null);
    try {
      await apiClient.cancelAtividade(atividade.id);
      setCancelSuccessMessage('Atividade cancelada com sucesso!');
      setCancelling(false);
      setShowCancelConfirm(false);
      reload();
    } catch (err: any) {
      setCancelError({
        erro: err.erro || 'ERRO_DESCONHECIDO',
        mensagem: err.mensagem || err.message || 'Erro ao cancelar atividade',
      });
      setCancelling(false);
    }
  };

  if (!selectedUserId) {
    return (
      <div>
        <p>Nenhum usuário selecionado. Por favor, selecione um usuário de demonstração para acessar o sistema.</p>
        <p>
          <Link to="/">Voltar para a programação</Link>
        </p>
      </div>
    );
  }

  return (
    <div className="atividade-detalhe-container" style={{ padding: '1rem 0' }}>
      <p>
        <Link to="/" className="voltar-link">Voltar para a programação</Link>
      </p>

      {userPapel === 'organizacao' && atividade && !isCancelada && !cancelSuccessMessage && (
        <div style={{ margin: '1rem 0', display: 'flex', gap: '1rem' }}>
          <Link
            to={`/atividades/${atividade.id}/editar`}
            className="editar-atividade-link"
            style={{
              padding: '0.4rem 0.8rem',
              backgroundColor: '#ffc107',
              color: '#000',
              borderRadius: '4px',
              textDecoration: 'none',
              display: 'inline-block',
            }}
          >
            Editar atividade
          </Link>

          <button
            type="button"
            onClick={() => setShowCancelConfirm(true)}
            className="cancelar-atividade-btn"
            style={{
              padding: '0.4rem 0.8rem',
              backgroundColor: '#dc3545',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
            }}
          >
            Cancelar atividade
          </button>
        </div>
      )}

      {showCancelConfirm && (
        <div
          className="cancel-confirm-box"
          role="alertdialog"
          aria-labelledby="cancel-dialog-title"
          aria-modal="true"
          style={{ border: '1px solid #dc3545', padding: '1rem', margin: '1rem 0', borderRadius: '4px', backgroundColor: '#fff5f5' }}
        >
          <p id="cancel-dialog-title">Tem certeza de que deseja cancelar esta atividade?</p>
          {cancelError && (
            <div className="error-message" role="alert" style={{ color: 'red', margin: '0.5rem 0' }}>
              Erro ({cancelError.erro}): {cancelError.mensagem}
            </div>
          )}
          <div style={{ display: 'flex', gap: '1rem', marginTop: '0.5rem' }}>
            <button
              type="button"
              disabled={cancelling}
              onClick={handleConfirmCancel}
              style={{
                padding: '0.5rem 1rem',
                backgroundColor: cancelling ? '#cccccc' : '#dc3545',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: cancelling ? 'not-allowed' : 'pointer',
              }}
            >
              {cancelling ? 'Cancelando atividade...' : 'Confirmar cancelamento'}
            </button>
            <button
              type="button"
              disabled={cancelling}
              onClick={() => setShowCancelConfirm(false)}
              style={{
                padding: '0.5rem 1rem',
                backgroundColor: '#6c757d',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: cancelling ? 'not-allowed' : 'pointer',
              }}
            >
              Manter atividade
            </button>
          </div>
        </div>
      )}

      {cancelSuccessMessage && (
        <div className="success-message" role="status" aria-live="polite" style={{ color: 'green', margin: '1rem 0' }}>
          {cancelSuccessMessage}
        </div>
      )}

      {loading && <p role="status" aria-live="polite">Carregando atividade...</p>}

      {error && (
        <div className="error-message" role="alert">
          Erro ({error.erro}): {error.mensagem}
        </div>
      )}

      {!loading && !error && atividade && (
        <div>
          {isCancelada && (
            <div style={{ color: 'red', fontWeight: 'bold', marginBottom: '1rem' }}>
              Atividade Cancelada
            </div>
          )}

          <h2 data-testid="detalhe-titulo">{atividade.titulo}</h2>
          <p><strong>Tipo:</strong> <span data-testid="detalhe-tipo">{atividade.tipo}</span></p>
          <p><strong>Sala:</strong> <span data-testid="detalhe-sala">{getSalaNome(atividade.salaId)}</span></p>
          <p><strong>Vagas:</strong> <span data-testid="detalhe-vagas">{atividade.vagas}</span></p>
          <p><strong>Carga Horária:</strong> <span data-testid="detalhe-carga">{atividade.cargaHorariaMinutos}</span> minutos</p>
          <p><strong>Situação:</strong> <span data-testid="detalhe-situacao">{atividade.situacao}</span></p>
          <p><strong>Ocupadas:</strong> <span data-testid="detalhe-ocupadas">{atividade.ocupadas}</span></p>
          <p><strong>Vagas Restantes:</strong> <span data-testid="detalhe-vagas-restantes">{atividade.vagasRestantes}</span></p>
          <p><strong>Pessoas em Espera:</strong> <span data-testid="detalhe-em-espera">{atividade.emEspera}</span></p>

          <h3>Encontros</h3>
          {atividade.encontros && atividade.encontros.length > 0 ? (
            <ul>
              {atividade.encontros.map((enc) => (
                <li key={enc.id}>
                  Início: {formatarDataHoraBrasilia(enc.inicio)} | Fim: {formatarDataHoraBrasilia(enc.fim)}
                </li>
              ))}
            </ul>
          ) : (
            <p>Nenhum encontro cadastrado.</p>
          )}

          <M2ExtensionPoint />
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { MemoryRouter, Routes, Route } from 'react-router-dom';
import { useSelectedUser } from './hooks/useSelectedUser';
import { UserSelector } from './components/UserSelector';
import { useProgramacao, DIAS_SEMANA } from './hooks/useProgramacao';
import { Programacao } from './components/Programacao';
import { AtividadeDetalhe } from './components/AtividadeDetalhe';
import { CriarAtividade } from './components/CriarAtividade';
import { EditarAtividade } from './components/EditarAtividade';
import { api } from './api/client';

interface AppProps {
  apiClient?: typeof api;
  initialEntries?: string[];
}

export function App({ apiClient = api, initialEntries }: AppProps) {
  const { selectedUser, selectUser, users } = useSelectedUser();
  const {
    dia,
    setDia,
    tipo,
    setTipo,
    atividades,
    salas,
    loading,
    error,
  } = useProgramacao(selectedUser?.id || null, apiClient);

  const content = (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <header>
        <h1>Semana Acadêmica</h1>
      </header>
      <main>
        <UserSelector
          selectedUser={selectedUser}
          onSelectUser={selectUser}
          users={users}
        />

        <div style={{ marginTop: '2rem' }} data-testid="active-user-info">
          {selectedUser ? (
            <div>
              <p>Usuário ativo: <strong>{selectedUser.nome}</strong> ({selectedUser.papel})</p>
              <Routes>
                <Route
                  path="/"
                  element={
                    <Programacao
                      dia={dia}
                      setDia={setDia}
                      tipo={tipo}
                      setTipo={setTipo}
                      atividades={atividades}
                      salas={salas}
                      loading={loading}
                      error={error}
                      dias={DIAS_SEMANA}
                      userPapel={selectedUser.papel}
                    />
                  }
                />
                <Route
                  path="/atividades/nova"
                  element={<CriarAtividade selectedUserId={selectedUser.id} userPapel={selectedUser.papel} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id/editar"
                  element={<EditarAtividade selectedUserId={selectedUser.id} userPapel={selectedUser.papel} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id"
                  element={<AtividadeDetalhe selectedUserId={selectedUser.id} userPapel={selectedUser.papel} apiClient={apiClient} />}
                />
              </Routes>
            </div>
          ) : (
            <div>
              <p>Nenhum usuário selecionado. Por favor, selecione um usuário de demonstração para acessar o sistema.</p>
              <Routes>
                <Route
                  path="/atividades/nova"
                  element={<CriarAtividade selectedUserId={null} userPapel={undefined} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id/editar"
                  element={<EditarAtividade selectedUserId={null} userPapel={undefined} apiClient={apiClient} />}
                />
                <Route
                  path="/atividades/:id"
                  element={<AtividadeDetalhe selectedUserId={null} apiClient={apiClient} />}
                />
                <Route path="*" element={null} />
              </Routes>
            </div>
          )}
        </div>
      </main>
    </div>
  );

  if (initialEntries) {
    return (
      <MemoryRouter initialEntries={initialEntries}>
        {content}
      </MemoryRouter>
    );
  }

  return content;
}

export default App;

