input.content:
:root {
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --bg-color: #f4f6f9;
  --surface-color: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --primary-color: #1e3a8a;
  --primary-hover: #1e40af;
  --accent-color: #0284c7;
  --border-color: #e2e8f0;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
  --success-bg: #d1fae5;
  --success-text: #065f46;
  --warning-bg: #fef3c7;
  --warning-text: #92400e;
  --danger-bg: #fee2e2;
  --danger-text: #991b1b;
  --info-bg: #e0f2fe;
  --info-text: #0369a1;
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-main);
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}

header.app-header {
  background: linear-gradient(135deg, var(--primary-color), #312e81);
  color: #ffffff;
  padding: 2.5rem 2rem;
  box-shadow: var(--shadow-md);
}

header.app-header h1 {
  margin: 0 0 0.5rem 0;
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}

header.app-header p {
  margin: 0;
  color: #93c5fd;
  font-size: 1rem;
}

main.app-main {
  max-width: 1100px;
  margin: -1.5rem auto 3rem auto;
  padding: 0 1.5rem;
}

.card {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  margin-bottom: 1.5rem;
}

.user-selector-container {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  padding: 1.25rem 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.user-selector-container label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.user-selector-container select,
.form-control {
  font-family: inherit;
  font-size: 1rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: #f8fafc;
  color: var(--text-main);
  width: 100%;
  box-sizing: border-box;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.user-selector-container select:focus,
.form-control:focus {
  outline: none;
  border-color: var(--accent-color);
  box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.15);
  background-color: #ffffff;
}

.active-user-info {
  background-color: var(--surface-color);
  border-left: 4px solid var(--accent-color);
  padding: 1rem 1.25rem;
  border-radius: var(--radius-sm);
  margin-top: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.active-user-info p {
  margin: 0;
  font-size: 0.95rem;
}

.programacao-container h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text-main);
}

.filtros-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.5rem;
  background-color: var(--surface-color);
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.dias-navegacao {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.dias-navegacao button {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background-color: #f8fafc;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
}

.dias-navegacao button:hover {
  background-color: #f1f5f9;
  color: var(--text-main);
}

.dias-navegacao button.active-day {
  background-color: var(--primary-color);
  color: #ffffff;
  border-color: var(--primary-color);
  box-shadow: var(--shadow-sm);
}

.tipo-filtro {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.tipo-filtro label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  white-space: nowrap;
  margin: 0;
}

.tipo-filtro select {
  padding: 0.5rem 0.75rem;
  font-size: 0.9rem;
  background-color: #f8fafc;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.atividades-list {
  list-style: none;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.25rem;
}

.atividade-item {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.atividade-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.atividade-cancelada {
  background-color: #fffbfa;
  border-color: #fecdd3;
}

.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 50px;
}

.badge-prevista { background-color: var(--info-bg); color: var(--info-text); }
.badge-andamento { background-color: var(--warning-bg); color: var(--warning-text); }
.badge-encerrada { background-color: var(--success-bg); color: var(--success-text); }
.badge-cancelada { background-color: var(--danger-bg); color: var(--danger-text); }

.btn-primary {
  display: inline-block;
  background-color: var(--primary-color);
  color: #ffffff;
  padding: 0.6rem 1.25rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  text-align: center;
  border: none;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: background-color 0.15s ease;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  display: inline-block;
  background-color: #f1f5f9;
  color: var(--text-main);
  padding: 0.6rem 1.25rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  text-align: center;
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.btn-secondary:hover {
  background-color: #e2e8f0;
}

.btn-danger {
  background-color: var(--danger-color);
  color: #ffffff;
}

.btn-danger:hover {
  background-color: #b91c1c;
}

.btn-warning {
  background-color: var(--warning-color);
  color: #78350f;
}

.btn-warning:hover {
  background-color: #d97706;
  color: #ffffff;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1rem;
  margin: 1.5rem 0;
}

.metric-card {
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 1rem;
  text-align: center;
}

.metric-card .value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-top: 0.25rem;
}

.metric-card .label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}

.error-message {
  background-color: var(--danger-bg);
  color: var(--danger-text);
  border: 1px solid #fecaca;
  padding: 1rem;
  border-radius: var(--radius-sm);
  margin: 1rem 0;
  font-weight: 500;
}

.success-message {
  background-color: var(--success-bg);
  color: var(--success-text);
  border: 1px solid #a7f3d0;
  padding: 1rem;
  border-radius: var(--radius-sm);
  margin: 1rem 0;
  font-weight: 500;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-weight: 600;
  font-size: 0.9rem;
  margin-bottom: 0.4rem;
  color: var(--text-main);
}

fieldset {
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
  background-color: #fafafa;
}

fieldset legend {
  font-weight: 600;
  padding: 0 0.5rem;
  color: var(--primary-color);
}

@media (max-width: 768px) {
  header.app-header {
    padding: 1.5rem 1rem;
  }
  main.app-main {
    padding: 0 1rem;
  }
  .filtros-container {
    flex-direction: column;
    align-items: stretch;
  }
  .dias-navegacao {
    overflow-x: auto;
    padding-bottom: 0.5rem;
  }
}

